// AiXenix Cosmos Lab: camera flight between two points of the universe frame. Kinematic presentation only (no ship,
// no physics, no relativity): the path is the straight segment, and progress along it is logarithmic in distance from
// the start and the end, so a flight crosses metres-to-megaparsecs gaps with a readable pace: it leaves the origin
// slowly, cruises across orders of magnitude and arrives slowly. Duration grows with log10 of the distance.

import { C_MPS, PC_M } from './frames';
import type { FlightOptions, FlightPlan, Vec3 } from './types';

/** Distance (pc) treated as "arrived": 1 au. */
const NEAR_PC = 1 / 206264.80624709636;

function smootherstep(x: number): number {
  const t = Math.min(1, Math.max(0, x));
  return t * t * t * (t * (6 * t - 15) + 10);
}

export function flightPlan(from: Vec3, to: Vec3, opts: FlightOptions = {}): FlightPlan {
  for (const v of [from, to]) if (!Array.isArray(v) || v.length !== 3 || !v.every(Number.isFinite)) throw new Error('cosmos: flight endpoints must be finite vectors');
  const minS = Number.isFinite(opts.minSeconds) ? Math.max(0.1, opts.minSeconds!) : 2;
  const maxS = Number.isFinite(opts.maxSeconds) ? Math.max(minS, opts.maxSeconds!) : 14;
  const d = Math.hypot(to[0] - from[0], to[1] - from[1], to[2] - from[2]);
  const decades = Math.log10(Math.max(d, NEAR_PC) / NEAR_PC); // 0 .. ~12 for Local Group distances
  const durationS = d === 0 ? minS : Math.min(maxS, Math.max(minS, minS + (maxS - minS) * (decades / 12)));
  // Fraction of the path covered at normalised time x: log-symmetric about the midpoint.
  const half = d / 2;
  const lnSpan = Math.log(Math.max(half, NEAR_PC) / NEAR_PC);
  const fraction = (x: number): number => {
    if (d === 0) return 1;
    const s = smootherstep(x);
    if (half <= NEAR_PC) return s;
    // s in [0, 0.5]: distance from the start grows as NEAR·e^(2s·lnSpan); mirrored for the second half.
    const dist = s <= 0.5 ? NEAR_PC * Math.exp(2 * s * lnSpan) - NEAR_PC * (1 - 2 * s) : d - (NEAR_PC * Math.exp(2 * (1 - s) * lnSpan) - NEAR_PC * (1 - 2 * (1 - s)));
    return Math.min(1, Math.max(0, dist / d));
  };
  const positionAt = (t: number): Vec3 => {
    const f = fraction(t / durationS);
    return [from[0] + (to[0] - from[0]) * f, from[1] + (to[1] - from[1]) * f, from[2] + (to[2] - from[2]) * f];
  };
  const speedAt = (t: number) => {
    const dt = durationS * 1e-4;
    const a = positionAt(Math.max(0, t - dt));
    const b = positionAt(Math.min(durationS, t + dt));
    const span = Math.min(durationS, t + dt) - Math.max(0, t - dt);
    const pcPerS = span > 0 ? Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]) / span : 0;
    return { pcPerS, c: (pcPerS * PC_M) / C_MPS };
  };
  return { from: [...from] as Vec3, to: [...to] as Vec3, distancePc: d, durationS, positionAt, speedAt };
}
