/** Galaxy summaries (same objects as universe.galaxies). */
export function listGalaxies(u: Universe) {
  return u.galaxies;
}

/** The local system of a model star (by star or address). Throws on an invalid address (use resolveAddress first). */
export function generateSystem(u: Universe, starOrAddress: ModelStar | string, opts: SystemOptions = {}): CosmosScene {
  let star: ModelStar;
  if (typeof starOrAddress === 'string') {
    const r = resolveAddress(u, starOrAddress);
    if (!r.ok) throw new Error(`cosmos: ${r.error}: ${r.message}`);
    star = r.star;
  } else {
    const r = resolveAddress(u, starOrAddress.address);
    if (!r.ok) throw new Error(`cosmos: ${r.error}: ${r.message}`);
    star = r.star;
  }
  const g = galaxyState(u, star.galaxyId)!;
  const props = modelStarProps(u, star)!;
  return buildSystem({ key: star.key, galaxyId: star.galaxyId, name: star.name, props, seed: systemSeed(star.address.id, g), provenance: 'procedural' }, opts);
}

/**
 * The local system of an observed star: the star from its catalogue values (fields not in the record are marked
 * reconstructed); planets only with hypotheticalPlanets (then procedural, flagged candidate). Stars with a catalogue
 * scene (record.sceneId) should open that scene instead.
 */
export function generateSystemForObservedStar(u: Universe, star: ObservedStar | KnownStarInput, opts: SystemOptions = {}): CosmosScene {
  const obs = 'provenance' in star && star.provenance === 'observed' ? (star as ObservedStar) : observedStars(u).find((o) => o.record.id === (star as KnownStarInput).id);
  if (!obs) throw new Error(`cosmos: observed star '${(star as KnownStarInput).id}' has no usable position`);
  const fields: Record<string, { kind: string; source?: string; note?: string }> = {};
  for (const [field, key] of [
    ['massSun', 'mass_kg'],
    ['radiusSun', 'radius_m'],
    ['teffK', 'star.teff_k'],
    ['luminositySun', 'star.luminosity_w'],
  ] as const) {
    fields[key] = obs.reconstructed.includes(field) ? { kind: 'reconstructed', note: 'from spectral-type / mass relations' } : { kind: 'observed', source: 'catalogue' };
  }
  return buildSystem(
    { key: obs.key, galaxyId: 'milky_way', name: obs.name, props: observedProps(obs), seed: hashString(`aixenix.cosmos/obs/${obs.record.id}`), provenance: 'observed', observedFields: fields },
    opts,
  );
}
